local HistoryLayer = class("SG_History")


local coinData = nil
local friendData = nil

local firstOpen = true
local isDetail = false

local WinColor =  cc.c3b(0x0E, 0xEF, 0x0E)
local LoseColor =  cc.c3b(0xf7,0x07, 0x2e)


function HistoryLayer:removeScene()

    local SG_History = SCENENOW["scene"]:getChildByName("SG_History")
    if  SG_History then
        SG_History:removeFromParent() --清除界面，内存不减少，专门用cs做的界面
    end

end



function HistoryLayer:showNewHistoryLayer()
    self:removeScene()
    local s = cc.CSLoader:createNode(SG_ResultCsb_filePath):addTo(SCENENOW["scene"])
    s:setName("SG_History"):setScale(1280/1920)
    self.btn_close = s:getChildByName("btn_close")
    self.btn_zhanji = s:getChildByName("btn_zhanji")
    self.btn_zenfen = s:getChildByName("btn_zenfen")
    self.btn_defen = s:getChildByName("btn_defen")
    self.item = s:getChildByName("item")
    self.item_z =s:getChildByName("item_z")
    self.item_d =s:getChildByName("item_d")
    self.listView = s:getChildByName("listView")
    local function TouchEventListener(sender, event)
        if event == TOUCH_EVENT_BEGAN then
            sender:setScale(0.8)
        end

        --触摸取消
        if event == TOUCH_EVENT_CANCELED then
            sender:setScale(1.0)
        end

        --触摸结束
        if event == TOUCH_EVENT_ENDED then
            sender:setScale(1.0)
            if sender == self.btn_close then
                self:removeScene()
            elseif sender == self.btn_zhanji then
                dump("zhanjigg")
                self:zhanJi()
            elseif sender == self.btn_zenfen then
                self:queryGold(1)
            elseif sender == self.btn_defen then
                self:queryGold(2)
            end

        end
    end
    self.btn_close:addTouchEventListener(TouchEventListener)
    self.btn_zhanji:addTouchEventListener(TouchEventListener)
    self.btn_zenfen:addTouchEventListener(TouchEventListener)
    self.btn_defen:addTouchEventListener(TouchEventListener)
    self:zhanJi()
end

function HistoryLayer:zhanJi()
    local tbl = {}
    tbl["playerId1"] = USER_INFO["uid"]
    tbl["currentPage"] = 1
    self.listView:removeAllItems()
    cct.createHttRq({
        url=HttpAddr .. "/queryPlayerWaiWeiHistory",--http://120.76.133.49:80/hbiInterface/goods/queryGoodsList
        date=tbl,
        type_="POST",
        callBack = function ( data )
            local netData = data.netData
            netData = json.decode(netData)
            dump(netData,"playerXXX")
            if netData.returnCode == "0" then
                for k,v in ipairs(netData.data) do
                    local item = self.item:clone()
                    local text_no = item:getChildByName("text_no")
                    text_no:setString(v.orderId)
                    local time_text = item:getChildByName("time_text")
                    local time_str = tonumber(v.createTime)
                    if time_str  then
                        time_str = os.date("%Y-%m-%d %H:%M:%S", v.createTime/1000)
                    else
                        time_str = v.createTime
                    end
                    time_text:setString(time_str)
                    local ya_text = item:getChildByName("ya_text")
                    local money = v.money
                    if appName == "真赢棋牌" then
                        money = money/100
                    end
                    ya_text:setString(money)
                    local gold_text = item:getChildByName("gold_text")
                    local result = v.result
                    if appName == "真赢棋牌" then
                        result = result/100
                    end
                    gold_text:setString(result)
                    self.listView:pushBackCustomItem(item)
                end
            else
                require(CommonTips_filePath):showTips("提示", "", 3, netData.error)
            end
        end
    })
end
function HistoryLayer:queryGold(type)
    local tbl = {}
    tbl["playerId1"] = USER_INFO["uid"]
    tbl["currentPage"] = 1
    tbl["type"] = type
    self.listView:removeAllItems()
    cct.createHttRq({
        url=HttpAddr .. "/queryPlayerXXX",--http://120.76.133.49:80/hbiInterface/goods/queryGoodsList
        date=tbl,
        type_="POST",
        callBack = function ( data )
            local netData = data.netData
            netData = json.decode(netData)
            dump(netData,"playerXXX")
            if netData.returnCode == "0" then
                for k,v in ipairs(netData.data) do
                    local item
                    if type == 1 then
                        item= self.item_z:clone()
                        local ya_text = item:getChildByName("ya_text")
                        ya_text:setString(v.toUserId)
                    elseif type ==2 then
                        item= self.item_d:clone()
                        local ya_text = item:getChildByName("ya_text")
                        ya_text:setString(v.userId)
                    end
                    local text_no = item:getChildByName("text_no")
                    text_no:setString(v.id)
                    local time_text = item:getChildByName("time_text")
                    local time_str = tonumber(v.createTime)
                    if time_str  then
                        time_str = os.date("%Y-%m-%d %H:%M:%S", v.createTime/1000)
                    else
                        time_str = v.createTime
                    end
                    time_text:setString(time_str)

                    local gold_text = item:getChildByName("gold_text")
                    local roomcardNum = v.roomcardNum
                    if appName == "真赢棋牌" then
                        roomcardNum = roomcardNum/100
                    end
                    gold_text:setString(roomcardNum)
                    self.listView:pushBackCustomItem(item)
                end
            else
                require(CommonTips_filePath):showTips("提示", "", 3, netData.error)
            end
        end
    })
end

return HistoryLayer